       (select count(*) from pb_ai.kb_chunks k join (values (291, $kb$ca-dig-alert-4216-1$kb$, md5($kb${"id": "ca-dig-alert-4216-1", "url": "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=GOV&sectionNum=4216.2.", "text": "California's one-call law is Government Code 4216 to 4216.24. There are two regional notification centers: Underground Service Alert of Southern California (DigAlert, digalert.org) and USA North 811 (usanorth811.org) for the rest of the state; dialing 811 or going online reaches the right one. Process: (1) delineate (white-line) the dig area before you call (4216.2(a)); (2) file the ticket at least 2 working days before digging, not counting the day you call, and not more than 14 calendar days before (4216.2(b)); (3) operators mark their lines or report no conflict by the legal start date and post an electronic positive response you can check on the ticket (4216.3); (4) inside the tolerance zone (24 inches each side of the mark) find the line with hand tools, or vacuum excavation if the operator agreed, before any power equipment (4216.4); (5) the ticket is good for 28 days; renew by the end of the 28th day or stop digging (4216.2(e), (i)). Private lines past the operator's service point are not marked. This is a plain-language summary; the law and the center's excavator manual govern.", "title": "California 811: DigAlert and USA North, how a locate request works (Gov Code 4216)", "topic": "Utility locates in California: Gov Code 4216, DigAlert and USA North 811", "source": "California Government Code 4216, 4216.2, 4216.3, 4216.4 (as amended through Jan. 1, 2025); DigAlert and USA North 811 excavator guidance", "confidence": "high"}$kb$::jsonb::text)), (364, $kb$emp-ca-safety-1$kb$, md5($kb${"id": "emp-ca-safety-1", "url": "https://www.law.cornell.edu/regulations/california/8-CCR-3395", "text": "Cal/OSHA's outdoor heat standard (8 CCR 3395) covers every outdoor job in California, including trench and pipe crews (as of Nov 5, 2026). Water: fresh, pure, suitably cool and free, close to the work, at least 1 quart per worker per hour for the whole shift (or a way to refill it). Shade: when it is over 80 F the employer must keep shade up while workers are present, big enough for everyone on a rest, recovery or meal break to sit in it fully shaded; at or below 80 F shade must be provided on request. Cool-down: anyone can take a preventative cool-down rest in the shade when they feel they need it, for at least 5 minutes, and must be checked for symptoms. At 95 F or above, construction must also run high-heat procedures. A written Heat Illness Prevention Plan must be at the site. For a specific case, ask HR, a labor attorney or the California Labor Commissioner (dir.ca.gov/dlse).", "title": "California heat illness rules for construction: water, shade, 80 F and 95 F triggers", "topic": "Employment law: California heat, safety, injuries, public works and worker status", "source": "8 CCR 3395 Heat Illness Prevention in Outdoor Places of Employment (Cal/OSHA); checked 2026-11-05", "confidence": "high"}$kb$::jsonb::text)), (365, $kb$emp-ca-safety-2$kb$, md5($kb${"id": "emp-ca-safety-2", "url": "https://www.law.cornell.edu/regulations/california/8-CCR-3395", "text": "When it is 95 F or hotter, Cal/OSHA's heat standard requires extra steps for construction, agriculture, landscaping, oil and gas extraction and hauling of construction materials (as of Nov 5, 2026): effective communication so any worker can reach a supervisor (voice, radio or phone that works in the area); observing workers for alertness and heat symptoms by a supervisor watching 20 or fewer people, a mandatory buddy system, regular contact with anyone working alone, or another effective method; designating who will call 911 / emergency services; reminding everyone throughout the shift to drink water; and pre-shift meetings on these procedures and the right to cool-down rest. The extra 10-minute cool-down every 2 hours at 95 F is required for agriculture only, not construction. New workers on a high-heat job must be closely watched for their first 14 days, and everyone during a heat wave. For a specific case, ask HR, a labor attorney or the California Labor Commissioner (dir.ca.gov/dlse).", "title": "California high-heat procedures at 95 degrees for construction crews", "topic": "Employment law: California heat, safety, injuries, public works and worker status", "source": "8 CCR 3395 Heat Illness Prevention in Outdoor Places of Employment (Cal/OSHA) subsections (a)(2), (e), (g); checked 2026-11-05", "confidence": "high"}$kb$::jsonb::text)), (2371, $kb$cal-2$kb$, md5($kb${"id": "cal-2", "text": "California's outdoor heat rule (Title 8, section 3395): provide fresh, cool drinking water close to the work, enough for at least 1 quart per worker per hour for the whole shift, and encourage drinking it; provide shade when it's over 80 F, close enough and big enough for everyone on break, and allow cool-down rests in the shade whenever someone asks (at least 5 minutes); watch new and newly returned workers closely for their first 14 days (acclimatization); at 95 F and above use high-heat procedures (effective communication, observing workers, reminding them to drink, pre-shift meetings); have a written heat illness plan, training and an emergency response plan with directions to the site. Signs of heat illness or stroke: call for help and cool the person right away.", "title": "Cal/OSHA heat illness prevention (section 3395)", "topic": "Cal/OSHA rules crews run into", "source": "Cal. Code Regs. tit. 8, section 3395 (California)"}$kb$::jsonb::text)), (2773, $kb$dig-az-overview-1$kb$, md5($kb${"id": "dig-az-overview-1", "url": "https://azleg.gov/ars/40/00360-22.htm", "kind": "summary", "text": "Arizona's dig law is A.R.S. 40-360.21 to 40-360.32, enforced by the Arizona Corporation Commission. One center: Arizona 811. Mark the dig area with white lining before you call (40-360.22(C)); a person digging on a single-family home lot is excused. Operators must mark \"as promptly as practicable, but not later than two working days.\" Working days skip Saturday, Sunday, legal holidays and the Friday after Thanksgiving. You may not start \"before the location and marking are complete or the excavator is notified that marking is unnecessary.\" Marks are good for 15 working days from the date of marking. If work goes on, give notice at least 2 working days before they run out. Within 24 inches of a marked line, expose it carefully with hand tools and support it. Hit a line: tell the operator right away; gas or hazardous material, also call 911. Leave the hole open until the operator arrives. Fine: up to $5,000 per violation.", "tier": "core", "state": "AZ", "title": "Arizona 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Arizona 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "A.R.S. 40-360.21 to 40-360.28 (azleg.gov; statute copy in Southwest Gas \"Arizona Dig Law\" booklet, rev. Aug 2017)", "checked": "2026-11-20", "edition": "Statute as posted on azleg.gov, read Nov 20, 2026", "license": "gov-state", "confidence": "high", "supersedes": "dig-az"}$kb$::jsonb::text)), (2774, $kb$dig-ar-overview-1$kb$, md5($kb${"id": "dig-ar-overview-1", "url": "https://codes.findlaw.com/", "kind": "summary", "text": "Arkansas's dig law is the Arkansas Underground Facilities Damage Prevention Act, Ark. Code 14-271-101 and after. One center: Arkansas 811. Notice (14-271-112): \"at least two (2), but not more than ten (10), full working days before commencing\" the dig. The notice is \"effective for a period of twenty (20) working days from the date that the notice was given.\" Work not finished or marks gone: \"reinitiate the notice procedure,\" which means calling it in again with the normal wait. The tolerance zone, white lining rule, damage steps and fine amounts were not read in this pass and are not confirmed here. Until they are: hand dig or vacuum to find any marked line before a machine works near it, and if you hit a line call the owner, and 911 if gas or liquid is escaping.", "tier": "core", "state": "AR", "title": "Arkansas 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Arkansas 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Ark. Code 14-271-112 (FindLaw copy, current as of Mar 28, 2024, as quoted in tests/staged/locate_round3_nov20/raw_findings.md)", "checked": "2026-11-20", "edition": "FindLaw copy current as of March 28, 2024", "license": "gov-state", "confidence": "low", "supersedes": "dig-ar", "unconfirmed": "tolerance zone, white lining, damage steps, fine amounts"}$kb$::jsonb::text)), (2775, $kb$dig-co-overview-1$kb$, md5($kb${"id": "dig-co-overview-1", "url": "https://a-us.storyblok.com/f/1021538/x/160e66dfe5/excavator-handbook.pdf", "kind": "summary", "text": "Colorado's dig law is C.R.S. 9-1.5-101 to 9-1.5-108, with the Underground Damage Prevention Safety Commission hearing violations. One center: Colorado 811. Notice: \"at least two (2) full business days prior to any excavation,\" not counting the call day. Marks are good for 30 days from the ticket's due date, or until you can't see them, whichever is first. To go on, notify Colorado 811 at least 2 business days before the 30 days end; once it has run out you need a new ticket. Tolerance zone: the width of the line plus 18 inches on each side. Use non-destructive digging there (hand or vacuum). Check that every member on the ticket has posted a positive response before you dig. If one has not by the locate-by date, send an Excavator Re-Notification first. Hit a line: stop, notify 811 and the operator right away; gas release, clear the area and call 911.", "tier": "core", "state": "CO", "title": "Colorado 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Colorado 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Colorado 811 Excavator Handbook (last update Nov 2022) pp. 5-23, 27-45; C.R.S. 9-1.5-103", "checked": "2026-11-20", "edition": "Handbook last updated November 2022", "license": "summary", "confidence": "medium", "supersedes": "dig-co"}$kb$::jsonb::text)), (2779, $kb$dig-fl-overview-1$kb$, md5($kb${"id": "dig-fl-overview-1", "url": "https://flsenate.gov/Laws/Statutes/2025/Chapter556/All", "kind": "summary", "text": "Florida's dig law is chapter 556, the Underground Facility Damage Prevention and Safety Act. One center: Sunshine 811. Notice: \"not less than 2 full business days before beginning any excavation\" (10 full business days for underwater work). A ticket is valid for 30 calendar days. Not finished: give another notice for the part still to dig. Tolerance zone: 24 inches from the outer edge of either side of the marked line. Inside it, \"use increased caution\": hand dig, pothole, soft dig or vacuum. You must check the positive responses before you dig. Pre-mark in white when the site can't otherwise be identified. Hit a line: \"immediately notify the member operator\"; if gas or a hazardous substance escapes, call 911. Citations are $500 plus court costs, $2,500 for hazardous material pipelines.", "tier": "core", "state": "FL", "title": "Florida 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Sunshine 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Fla. Stat. ch. 556 (2025): 556.102, 556.105, 556.107, 556.108, 556.109, 556.114, 556.116", "checked": "2026-11-20", "edition": "2025 Florida Statutes", "license": "gov-state", "confidence": "high", "supersedes": "dig-fl"}$kb$::jsonb::text)), (2783, $kb$dig-il-overview-1$kb$, md5($kb${"id": "dig-il-overview-1", "url": "https://ilga.gov/legislation/ilcs/ilcs3.asp?ActID=1286", "kind": "summary", "text": "Illinois's dig law is the Underground Utility Facilities Damage Prevention Act, 220 ILCS 50, rewritten effective January 1, 2025 and enforced by the Illinois Commerce Commission. JULIE is the one-call center everywhere outside the City of Chicago; Chicago runs its own system (811 Chicago). Notice: \"not less than 2 days but no more than 10 days in advance.\" A \"day\" skips Saturdays, Sundays, JULIE holidays and the day of the notice. A normal notice is good for 25 days from the first request. An extension can be asked for from day 20 and adds 25 days. Pre-mark the dig area in white (black when there is snow on the ground). Since January 1, 2026: confirm every notified operator has posted a positive response before you dig. Tolerance zone: one and one-half feet (18 inches) on either side of the outside edge of the marked line. Hit a line: notify the owner and JULIE right away; gas or hazardous material escaping, call 911.", "tier": "core", "state": "IL", "title": "Illinois 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (JULIE; Chicago is separate)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "220 ILCS 50/2, 4, 5.1, 5.2, 5.3, 6, 7, 10, 11 (as amended by P.A. 103-614, eff. Jan 1, 2025)", "checked": "2026-11-20", "license": "gov-state", "effective": "2025-01-01", "confidence": "high", "supersedes": "dig-il"}$kb$::jsonb::text)), (2786, $kb$dig-ks-overview-1$kb$, md5($kb${"id": "dig-ks-overview-1", "url": "https://ksrevisor.gov/statutes/chapters/ch66/066_018_0004.html", "kind": "summary", "text": "Kansas's dig law is the Kansas Underground Utility Damage Prevention Act, K.S.A. 66-1801 to 66-1816, enforced by the Kansas Corporation Commission. One center: Kansas 811. Notice: \"at least two full working days but not more than 20 calendar days before the scheduled excavation start date.\" The notice, or any update, is \"valid for 20 calendar days after the excavation start date\" (changed from 15 days on January 1, 2024). Ticket only what you can reasonably finish in that time. To go on, update the notice. Do not make repeated remark requests unless the cause was out of your control; the Commission has warned of fines for needless updates. Whiteline the dig area when the operator asks for it. Pre-engineered and permitted projects still need the notice before digging starts. The tolerance zone (24 inches in K.S.A. 66-1802) and fine amounts were not re-read today and are not confirmed here.", "tier": "core", "state": "KS", "title": "Kansas 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Kansas 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "K.S.A. 66-1804 (ksrevisor.gov, as amended eff. Jan 1, 2024)", "checked": "2026-11-20", "license": "gov-state", "effective": "2024-01-01", "confidence": "medium", "supersedes": "dig-ks", "unconfirmed": "tolerance zone and fine amounts"}$kb$::jsonb::text)), (2787, $kb$dig-ky-overview-1$kb$, md5($kb${"id": "dig-ky-overview-1", "url": "https://law.justia.com/codes/kentucky/chapter-367/section-367-4911/", "kind": "summary", "text": "Kentucky's dig law is the Underground Facility Damage Prevention Act, KRS 367.4901 to 367.4917. One center: Kentucky 811. Notice: \"not less than two (2) full working days nor more than ten (10) full working days prior to commencing work.\" \"Locate requests are valid for twenty-one (21) calendar days from the day of the initial request.\" Ask for remarking two working days before each 21-day period ends, or sooner if the marks are gone or the plan changes. One request may not cover more than 5,000 feet unless you and the operator agree. Mark the edges of the dig yourself when an operator asks or the area can't be described. Operator did not respond in time: \"the excavator shall submit a second notice.\" If there is still nothing one working day later, an excavator who followed the law is not liable for damage to lines that would have been located (not true for certain gas and hazardous liquid pipelines). Inside the tolerance zone, \"hand-dig or use nonintrusive means.\" Machines are allowed for pavement, rock, and material more than 12 inches in any direction from the located line, with a watcher. Hit a line: stop and notify the operators; flammable, toxic or corrosive escape, call 911.", "tier": "core", "state": "KY", "title": "Kentucky 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Kentucky 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "KRS 367.4911 (Justia copy, effective Jan 1, 2022)", "checked": "2026-11-20", "license": "gov-state", "effective": "2022-01-01", "confidence": "high", "supersedes": "dig-ky"}$kb$::jsonb::text)), (2795, $kb$dig-mo-overview-1$kb$, md5($kb${"id": "dig-mo-overview-1", "url": "https://revisor.mo.gov/main/OneSection.aspx?section=319.026", "kind": "summary", "text": "Missouri's dig law is the Underground Facility Safety and Damage Prevention Act, RSMo 319.010 to 319.050 (amended August 28, 2025). One center: Missouri 811. Notice: \"at least two working days, but not more than ten working days, before the expected date\" of starting. You may work in the area on the notice, while the marks can be seen, until the \"notice of intent to excavate expiration date\" printed on the ticket; the number of days is not in this section and is not confirmed here. If you can't start within ten working days, make a relocate request before digging. Marks unusable: ask the center for a remark. White lining (paint, stakes, whiskers) may be used when the site can't be clearly described. Find a line unmarked or marked wrong: notify the center; the owner must contact you or mark it correctly within two hours. Hand or soft digging \"shall be used as a best practice when possible\"; no hand-dig distance is given in this section. Hit a line: notify the center. Gas or hazardous liquid pipeline release: \"immediately contact 911.\" Do not hide or repair damage without the owner's OK.", "tier": "core", "state": "MO", "title": "Missouri 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Missouri 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "RSMo 319.026 (revisor.mo.gov, effective Aug 28, 2025)", "checked": "2026-11-20", "license": "gov-state", "effective": "2025-08-28", "confidence": "medium", "supersedes": "dig-mo", "unconfirmed": "ticket life in days; tolerance zone"}$kb$::jsonb::text)), (2798, $kb$dig-nv-overview-1$kb$, md5($kb${"id": "dig-nv-overview-1", "url": "https://usanorth811.org/assets/PDF/Nevada-2025-Handbook.pdf", "kind": "summary", "text": "Nevada's dig law is NRS 455.080 to 455.180 with rules in NAC 455. One center: USA North 811. Call at least 2 working days (7 AM to 5 PM, not weekends or holidays, call day not counted) and not more than 28 calendar days before digging. Mark the dig area in white first. Wait for every operator: the handbook says excavators \"are required by law to wait until all operators\" have given a positive response, even if the start time on the ticket has passed. A ticket is good for 28 calendar days from the date and time of the notification. It can be extended twice, 28 days each; after that the regulation requires a new notification (NAC 455.165). That is 84 days at most on one ticket. Hand tools only within 24 inches on either side of the outside of the line. Hit a line: notify the operator right away; in an emergency also 911.", "tier": "core", "state": "NV", "title": "Nevada 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (USA North 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "USA North 811 Nevada Excavation Handbook (rev. Jan 2025) pp. 3-8, 21; NRS 455.110; NAC 455.165", "checked": "2026-11-20", "edition": "Handbook revised January 2025; NAC 455 revised Aug 2026", "license": "summary", "confidence": "high", "supersedes": "dig-nv"}$kb$::jsonb::text)), (2801, $kb$dig-nm-overview-1$kb$, md5($kb${"id": "dig-nm-overview-1", "url": "https://www.srca.nm.gov/parts/title18/18.060.0005.html", "kind": "summary", "text": "New Mexico's dig law is the Excavation Damage to Pipelines and Underground Utility Lines Act (NMSA 62-14) with rule 18.60.5 NMAC, enforced by the Public Regulation Commission's pipeline safety bureau. One center: NM811. Notice: 2 working days, not counting the day you call; operators must mark \"within two full working days from the effective date of the ticket.\" Marks are good for 15 working days from the end of the notice period. Marks gone with no offsets: stop and ask for a relocate, only for the part still to dig, and say why. Jobs longer than 15 working days: ask for a wide area conference at least two working days ahead, write a work plan signed by all, and reaffirm the wide area ticket every 15 working days. Pre-mark in white: it shows the actual dig, not the limits of construction. Before digging, check that every operator has marked or cleared. If one has not, call for a warning locate. Within 18 inches either side of a mark, expose the line first by non-mechanical means or vacuum. Hit a line: stop, call 911 if needed, the operator and 811, secure the site, and stay until released.", "tier": "core", "state": "NM", "title": "New Mexico 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (NM811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "18.60.5 NMAC sections 7, 8, 10, 11, 12, 13, 15, 16, 17 (Public Regulation Commission, srca.nm.gov)", "checked": "2026-11-20", "edition": "18.60.5 NMAC as posted Nov 20, 2026", "license": "gov-state", "confidence": "high", "supersedes": "dig-nm"}$kb$::jsonb::text)), (2802, $kb$dig-ny-overview-1$kb$, md5($kb${"id": "dig-ny-overview-1", "url": "https://dps.ny.gov/system/files/documents/2025/06/ss753-booklet-2025.05.09-update.pdf", "kind": "summary", "text": "New York's dig rules are 16 NYCRR Part 753 (\"Code Rule 753\") under General Business Law Article 36, enforced by the Public Service Commission. Two centers: UDig NY upstate and New York 811 for New York City and Long Island. Notice: \"at least two but not more than ten working days, not including the date of the call.\" There is no ticket expiry date. If you put the start off by more than ten working days, give a new notice. Do not start until you have heard from \"each and every operator\" that its lines are marked or that it has none. Use the Automated Positive Response system where there is one. Tolerance zone: half the known diameter plus two feet on each side of the center line (two feet each side if the size is not known). Verify the line's exact location before power equipment goes in the zone; gas and liquid petroleum lines must be found with hand-dug test holes. Hit a line: tell the operator right away; gas, liquid or electric emergency, clear the area and call 911.", "tier": "core", "state": "NY", "title": "New York 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (UDig NY, New York 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "16 NYCRR Part 753 (DPS booklet; Part 753 dated Feb 21, 2023); Gen. Bus. Law 765 (May 9, 2025)", "checked": "2026-11-20", "edition": "Part 753 as of February 21, 2023; booklet updated May 9, 2025", "license": "gov-state", "confidence": "high", "supersedes": "dig-ny"}$kb$::jsonb::text)), (2805, $kb$dig-oh-overview-1$kb$, md5($kb${"id": "dig-oh-overview-1", "url": "https://oups.org/wp-content/uploads/2026/06/OHIO811_Excavator-Manual_English_June-2026.pdf", "kind": "summary", "text": "Ohio's dig law is O.R.C. 3781.25 to 3781.38 (amended June 9, 2026); complaints go to the Underground Technical Committee at the PUCO. One center: OHIO811. Oil and gas producers answer through a separate group reached by the same call. Notice: \"at least two working days, not including the day of the notification,\" and \"not more than sixteen calendar days before commencing excavation.\" The law and the June 2026 manual give no ticket expiry date. Keep the ticket for the whole job and ask for a remark when marks fade. Premark the dig in white paint unless an exception applies. Check Positive Response before you go to the job; code 999 means an owner has not answered by the legal start. Tolerance zone: the width of the line plus 18 inches on each side. Dig there carefully, with a second person watching the bucket. Hit a line: get everyone safe, stop, notify the utility and OHIO811; anything flammable, toxic or corrosive escaping, call 911.", "tier": "core", "state": "OH", "title": "Ohio 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (OHIO811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "OHIO811 Excavator Manual (rev. June 2026) pp. 5-7, 10-17, 20-24, 40; O.R.C. 3781.25 to 3781.32", "checked": "2026-11-20", "edition": "Manual revised June 2026", "license": "summary", "confidence": "high", "supersedes": "dig-oh"}$kb$::jsonb::text)), (2807, $kb$dig-or-overview-1$kb$, md5($kb${"id": "dig-or-overview-1", "url": "https://digsafelyoregon.com/wp-content/uploads/2026/03/2026-Addendum-to-the-Oregon-Standards-Manual_Final.pdf", "kind": "summary", "text": "Oregon's dig rules are ORS 757.542 to 757.562 and OAR chapter 952, written by the Oregon Utility Notification Center (Oregon 811). Pre-mark the dig area in white, then call at least 2 full business days and not more than 10 business days before digging. Do not start until you have \"received a response from each operator of underground facilities in the area.\" Ticket life: 30 calendar days. The Center's 2026 Addendum says the rule was changed \"from 45 days to 30 days,\" effective January 8, 2026, and Oregon 811's own homeowner page says marks should no longer be used after 30 days. Older copies of the rule still say 45. Past ticket life, call in a new locate request. Tolerance zone: 24 inches around the outside of the line on all sides. Use hand tools or other non-invasive methods there. Hit a line: tell the operator right away; gas or hazardous liquid release, call 911. Don't bury it without the operator's OK.", "tier": "core", "state": "OR", "title": "Oregon 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Oregon 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "OAR 952-001-0010, -0050, -0070, -0090 (Oregon Utility Notification Center); 2026 Addendum to the Oregon Standards Manual (Mar 12, 2026); Oregon 811 homeowners page (read Nov 20, 2026)", "checked": "2026-11-20", "edition": "2026 Addendum, last updated March 12, 2026", "license": "gov-state", "effective": "2026-01-08", "confidence": "medium", "supersedes": "dig-or"}$kb$::jsonb::text)), (2817, $kb$dig-wa-overview-1$kb$, md5($kb${"id": "dig-wa-overview-1", "url": "https://lawfilesext.leg.wa.gov/law/RCWPDF/RCW%20%2019%20%20TITLE/RCW%20%2019%20.122%20%20CHAPTER/RCW%20%2019%20.122%20%20COMBINEDCHAPTER.pdf", "kind": "summary", "text": "Washington's dig law is RCW 19.122, enforced by the Utilities and Transportation Commission (UTC). Mark the boundary of the dig \"with white lining or, when necessary, white pin flags,\" then call 811. Notice: \"not less than two full business days and not more than 10 full business days\" before the work-to-begin date. Since January 1, 2026 you \"may not commence excavation until the excavator has received positive response\" from every operator with lines in the area. Marks expire 45 calendar days after you gave notice; to dig after that, give a new notice. Marks are accurate to within 24 inches of the outside of the line on both sides. Find the exact location before digging there: hand digging when practical, vacuum or air tools. Hit a line: tell the operator and 811, call 911 if it is an emergency, don't bury it, and report the damage to the UTC within 45 days.", "tier": "core", "state": "WA", "title": "Washington 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (Washington 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "RCW 19.122.020, .030, .031, .040, .050, .053, .055, .070 (through Laws 2025 c 292)", "checked": "2026-11-20", "edition": "RCW as amended through Laws of 2025 chapter 292", "license": "gov-state", "confidence": "high", "supersedes": "dig-wa"}$kb$::jsonb::text)), (2818, $kb$dig-wv-overview-1$kb$, md5($kb${"id": "dig-wv-overview-1", "url": "https://code.wvlegislature.gov/24C-1-5/", "kind": "summary", "text": "West Virginia's dig law is W. Va. Code Chapter 24C. One center: West Virginia 811. Notice: \"Not less than forty-eight hours, excluding Saturdays, Sundays and federal or state legal holidays,\" and not more than ten work days before work begins. Changing the start date or time: tell the one-call system at least 24 hours ahead, not counting weekends and holidays. The section sets no ticket life in days and no tolerance zone in inches; those are not confirmed here, so go by the ticket and West Virginia 811. Each equipment operator must be told to avoid damage, \"including hand digging, when necessary,\" to keep a clearance \"as may be reasonably necessary\" from lines given the reach of the cutting edge, to protect marks and stakes, and to support lines during work and backfill. Line hit: report it immediately and give the operator reasonable time to repair. An emergency: alert the public and call 911. Damage that is not an emergency: notify the one-call system within 24 hours. Failing to notify or to report is a misdemeanor with a fine of \"not more than $5,000,\" and you owe the repair cost.", "tier": "core", "state": "WV", "title": "West Virginia 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (West Virginia 811)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "W. Va. Code 24C-1-5 (code.wvlegislature.gov)", "checked": "2026-11-20", "edition": "W. Va. Code as posted Nov 20, 2026 (last act shown: 2006 SB 439)", "license": "gov-state", "confidence": "medium", "supersedes": "dig-wv", "unconfirmed": "ticket life and tolerance zone"}$kb$::jsonb::text)), (2820, $kb$dig-wy-overview-1$kb$, md5($kb${"id": "dig-wy-overview-1", "url": "https://law.counselstack.com/statute/wy/37-12-302", "kind": "summary", "text": "Wyoming's dig law is the Wyoming Underground Facilities Notification Act, Wyo. Stat. 37-12-301 to 37-12-307. One center: One-Call of Wyoming (811). Notice: \"at least two (2) full business days, but not more than fourteen (14) business days prior to any excavation.\" A job that runs longer than 14 business days needs the notice given again for each following 14 business day period. Mark the dig area before the locator comes, unless one operator can find the site from the address, there was a site meeting, or it is an emergency. Operators mark \"within twenty-four (24) inches horizontally\" of the outside of the line, in APWA colors, within two full business days. Reasonable care is always required, and it calls for hand or soft digging where needed to protect the line. Hit or touch a line: notify the operator and the center immediately. Gas or hazardous liquid released: call 911 first. Do not hide damage or repair it without authorization. In a dispute the excavator has to prove reasonable care. If the operator missed its deadline or marked wrong, an excavator who used reasonable care is not liable. Penalty amounts were not confirmed.", "tier": "core", "state": "WY", "title": "Wyoming 811 rules in short: wait before you dig, how long a ticket is good, hand-dig zone (One-Call of Wyoming)", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Wyo. Stat. 37-12-302 (Counsel Stack copy, 2026)", "checked": "2026-11-20", "edition": "Statute copy read Nov 20, 2026", "license": "gov-state", "confidence": "medium", "supersedes": "dig-wy", "unconfirmed": "penalty amounts"}$kb$::jsonb::text)), (2824, $kb$sp-wa-confined-1$kb$, md5($kb${"id": "sp-wa-confined-1", "url": "https://lawfilesext.leg.wa.gov/Law/WACArchive/2024/htm/WAC%20296%20-809%20%20CHAPTER/WAC%20296%20-809%20-099.htm", "kind": "summary", "note": "Adds the 296-809-099 definitions (read 2026-11-21). \"Not re-read on 2026-11-20\" replaced by the dates in edition.", "text": "Washington has one confined space rule for all industries, chapter 296-809 WAC, instead of the federal construction rule; OSHA's adoption table lists it as different but at least as effective. Air numbers match federal: flammables over 10 percent of the LFL or LEL, oxygen below 19.5 or above 23.5 percent (296-809-099). Its definitions add: any physical hazard (electrical shock, moving parts) makes a space permit-required; where the opening is big enough to fully enter, a permit is needed even for partial body entry; excavations and pits are among its examples. Permit (read 2026-11-19): the same 15 items as the federal general industry list, in another order (296-809-50004), with equipment to detect a rise in hazard if ventilation stops (federal construction item (e)); available at entry (50002(5)); problems noted on it (50002(7)); kept 1 year (50006(2)). Air is tested with a calibrated, direct-reading instrument (60004(3)(a)). The app's permit form covers these items.", "tier": "core", "state": "WA", "title": "Washington confined space rule (chapter 296-809 WAC): one rule for all industries", "topic": "State safety plan: confined space", "source": "WAC 296-809-099 (WSR 18-02-071, eff. 2/5/18), 296-809-50002, 296-809-50004, 296-809-50006, 296-809-60004", "checked": "2026-11-21", "edition": "Chapter 296-809 WAC: permit sections read 2026-11-19; 296-809-099 as archived 2024, read 2026-11-21", "license": "gov-state", "confidence": "medium", "supersedes": "sp-wa-confined-1"}$kb$::jsonb::text)), (2952, $kb$osha-pl-report-8-24-1$kb$, md5($kb${"id": "osha-pl-report-8-24-1", "url": "https://www.law.cornell.edu/cfr/text/29/1904.39", "kind": "summary", "text": "29 CFR 1904.39(a): report to OSHA within 8 hours after the death of any employee from a work-related incident, and within 24 hours after the in-patient hospitalization of one or more employees, an amputation, or the loss of an eye. How: call or go to the nearest OSHA Area Office, call 1-800-321-OSHA (1-800-321-6742), or use the online form at osha.gov. A voicemail, fax or email to a closed office does not count. A death is reportable only if it occurs within 30 days of the incident; a hospitalization, amputation or eye loss only if it occurs within 24 hours of the incident. If you learn of it later, the clock starts when you or your agent learn. In-patient hospitalization means formal admission for care or treatment; admission only for observation or tests is not reportable. A motor vehicle crash on a public road is reportable only if it happened in a construction work zone. All employers report, even those exempt from keeping the OSHA 300 log. Many state plans use shorter times or longer lists, so check the job's state.", "tier": "core", "state": "US", "title": "Reporting a death, a worker admitted to the hospital, an amputation or eye loss to federal OSHA: 8 and 24 hours", "topic": "Injury reporting and OSHA recordkeeping", "source": "29 CFR 1904.39(a)(1)-(3), (b)(1)-(11) (79 FR 56187, Sept. 18, 2014)", "checked": "2026-11-20", "edition": "eCFR current text, read 2026-11-20", "license": "gov-us", "confidence": "high"}$kb$::jsonb::text)), (2969, $kb$sp-ca-heat-1$kb$, md5($kb${"id": "sp-ca-heat-1", "url": "https://dir.ca.gov/Title8/3395.html", "kind": "summary", "text": "California's outdoor heat rule is 8 CCR 3395; construction gets the full rule including high-heat procedures. Water: fresh, cool, free and close to the work; where it is not plumbed, at least 1 quart per employee per hour for the whole shift. Shade: when the temperature is above 80 F, shade is up at all times while employees are present, close to the work, with room for everyone on a rest or recovery period to sit fully in the shade without touching each other; at or below 80 F, shade is provided or available on request. Anyone may take a preventative cool-down rest in the shade at any time, is watched and asked about symptoms, and is not ordered back to work until symptoms are gone, with at least 5 minutes in the shade plus the time to get there. Temperature here means the dry-bulb air temperature in the open. The employer has a written heat illness prevention plan, in English and the language most employees understand, available at the worksite. Federal OSHA has no heat standard in force.", "tier": "core", "state": "CA", "title": "California outdoor heat rule: water, shade at 80 F, cool-down rest", "topic": "State safety plan: heat illness", "source": "8 CCR 3395(a)-(d), (i)", "checked": "2026-11-20", "edition": "Title 8 CCR 3395, last substantive amendment operative 5-1-2015 (Register 2015, No. 14)", "license": "gov-state", "confidence": "high"}$kb$::jsonb::text)), (2970, $kb$sp-ca-heat-2$kb$, md5($kb${"id": "sp-ca-heat-2", "url": "https://dir.ca.gov/Title8/3395.html", "kind": "summary", "text": "California's 8 CCR 3395(e) high-heat procedures start when the temperature is 95 F or more, for construction and the other listed industries: keep voice, sight or phone contact so employees can reach a supervisor; observe employees for alertness and signs of heat illness by one of these: a supervisor watching 20 or fewer employees, a mandatory buddy system, regular contact with anyone working alone, or another effective way; name who is authorized to call emergency medical services; remind people to drink water; and hold a pre-shift meeting on the procedures. Acclimatization (3395(g)): all employees are closely observed during a heat wave, meaning a day predicted to reach at least 80 F and at least 10 degrees hotter than the average high of the last five days; and an employee newly assigned to a high heat area is closely observed for the first 14 days. Emergency response (3395(f)): act on symptoms at once, never leave a sick worker alone or send them home without first aid, and give responders clear directions to the site.", "tier": "core", "state": "CA", "title": "California high-heat procedures at 95 F, heat waves and new workers", "topic": "State safety plan: heat illness", "source": "8 CCR 3395(e), (f), (g)", "checked": "2026-11-20", "edition": "Title 8 CCR 3395, last substantive amendment operative 5-1-2015 (Register 2015, No. 14)", "license": "gov-state", "confidence": "high"}$kb$::jsonb::text)), (2971, $kb$sp-ca-report-1$kb$, md5($kb${"id": "sp-ca-report-1", "url": "https://www.dir.ca.gov/title8/342.html", "kind": "summary", "text": "California employers report to Cal/OSHA (the Division of Occupational Safety and Health) immediately, by telephone or the online mechanism, any serious injury or illness, or death, of an employee at work (8 CCR 342(a)). \"Immediately means as soon as practically possible but not longer than 8 hours after the employer knows\" or with diligent inquiry would have known. Only if the employer can show exigent circumstances may the report be made within 24 hours of the incident. Serious injury or illness is defined in 8 CCR 330(h), not in section 342; that definition was not re-read on 2026-11-20, so what counts as serious is not confirmed here. The report gives the time and date, employer name and contact, the site address, the injured person's name, the nature of the injury, where the person was taken, and a description of the accident and whether the scene was changed. The federal 24 hours for a hospitalization does not apply to a job covered by Cal/OSHA.", "tier": "core", "state": "CA", "title": "California injury reporting: serious injury or worker in the hospital, immediately and no later than 8 hours", "topic": "State safety plan: injury reporting", "source": "8 CCR 342(a)-(c); 8 CCR 330(h)", "checked": "2026-11-20", "edition": "Title 8 CCR 342, amended filed 1-28-2020 (Register 2020, No. 5)", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (2988, $kb$sp-mn-confined-1$kb$, md5($kb${"id": "sp-mn-confined-1", "url": "https://www.dli.mn.gov/sites/default/files/pdf/fact_trenching_excavation.pdf", "kind": "summary", "note": "New id in the ord of sp-mn-trench-1. The trench fact also sits in osha-pl-trench-states-2. \"Injury reporting times not read\" dropped: sp-mn-report-1 now has them.", "text": "Minnesota (MNOSHA) uses the federal confined space in construction rule, 29 CFR 1926 Subpart AA: the old state construction rule, Minn. R. 5207.0300 to 5207.0304, is marked repealed (42 SR 1015; read 2026-11-19). MNOSHA's page of differences from federal OSHA lists nothing for confined space or excavation. Trenches in this state follow the federal excavation rule, 29 CFR 1926.651 and 1926.652: protection from 5 ft, or shallower when a competent person sees signs of a possible cave-in; MNOSHA's trenching fact sheet states no state difference (read by an earlier check on 2026-11-20). Any state heat rule was not read; it is not confirmed here.", "tier": "core", "state": "MN", "title": "Minnesota confined space in construction: the federal rule (old state rule repealed)", "topic": "State safety plan: confined space", "source": "Minn. R. 5207.0300-.0304 (repealed, 42 SR 1015); MNOSHA differences page; MNOSHA trenching fact sheet; 29 CFR 1926 Subpart AA, 1926.651-652", "checked": "2026-11-20", "edition": "MNOSHA pages as read 2026-11-19 / 2026-11-20", "license": "gov-state", "confidence": "medium", "supersedes": "sp-mn-trench-1", "unconfirmed": "yes"}$kb$::jsonb::text)), (2994, $kb$sp-nv-who-1$kb$, md5($kb${"id": "sp-nv-who-1", "url": "https://www.osha.gov/stateplans/NV", "kind": "summary", "text": "Nevada OSHA has incorporated most federal OSHA standards by reference, according to OSHA's page for the state's plan. Its unique standards listed there are, for construction, cranes, steel erection and asbestos, and for general industry, safety programs, explosives, sanitation and hazard communication. Excavation and confined space are not on the list, so trench protection is the federal 5 ft rule (29 CFR 1926.652) and confined space in construction is 29 CFR 1926 Subpart AA. A written safety program is required of employers with more than 10 employees (NRS 618.383, as described in Nevada OSHA's heat guidance). The state's injury reporting rule was not read; it is not confirmed whether it differs from the federal 8 and 24 hours. Federal OSHA covers military bases, land under exclusive federal jurisdiction and tribal land.", "tier": "core", "state": "NV", "title": "Nevada: federal rules by reference, plus state safety program rules", "topic": "State safety plan: who enforces and what differs", "source": "OSHA Nevada State Plan page; NRS 618.383", "checked": "2026-11-20", "edition": "OSHA State Plan page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3002, $kb$sp-tn-who-1$kb$, md5($kb${"id": "sp-tn-who-1", "url": "https://lwdsupport.tn.gov/hc/en-us/articles/115013202707-Differences-in-TOSHA-and-Federal-OSHA-Standards", "kind": "summary", "text": "Tennessee's plan, TOSHA, has adopted the federal standards for private and public employers. TOSHA's own page of differences lists, for construction (29 CFR 1926), only that four administrative sections are not adopted (1926.1 to 1926.4); nothing differs for excavation, confined space or fall protection. So trench protection is from 5 ft (29 CFR 1926.652) and confined space in construction is 29 CFR 1926 Subpart AA. The state rules that go beyond federal are the Hazardous Chemical Right to Know rule (Rule 0800-01-09) on top of hazard communication, a sharps injury rule, and the state's own air contaminant limits (Rule 0800-1-1-.07(2)(b)) in place of 29 CFR 1910.1000. The state's injury reporting times and any heat rule were not read; they are not confirmed here. Federal OSHA covers Tennessee Valley Authority facilities, military bases and railroad employment.", "tier": "core", "state": "TN", "title": "Tennessee: TOSHA uses the federal construction rules", "topic": "State safety plan: who enforces and what differs", "source": "TOSHA, Differences in TOSHA and Federal OSHA Standards; OSHA Tennessee State Plan page; Tenn. Rules 0800-01-09, 0800-1-1-.07", "checked": "2026-11-20", "edition": "TOSHA page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3003, $kb$sp-nc-who-1$kb$, md5($kb${"id": "sp-nc-who-1", "url": "https://www.labor.nc.gov/north-carolina-state-specific-standards", "kind": "summary", "text": "North Carolina's plan (NC Department of Labor, OSH Division) publishes a list of its state-specific standards. For construction they are 13 NCAC 07F .0202 (general safety and health provisions), .0203 (occupational health and environmental controls), .0204 (personal protective and life saving equipment), .0205 (steel erection) and .0207 (toxic and hazardous substances), plus communication tower and blasting rules. Rule .0202 rewords 29 CFR 1926.28(a): the employer is responsible for requiring appropriate personal protective equipment in all operations where there is an exposure to hazardous conditions. The state also has rules on safety and health programs and committees (13 NCAC 07A .0600 to .0606) and a Hazardous Chemical Right to Know Act. Excavation and confined space are not on the list, so trench protection is the federal 5 ft rule (29 CFR 1926.652). Who must have a safety committee, the state's reporting times and any heat rule were not read; they are not confirmed here.", "tier": "core", "state": "NC", "title": "North Carolina: state-specific standards and the trench rule", "topic": "State safety plan: who enforces and what differs", "source": "NCDOL, North Carolina State-Specific Standards; 13 NCAC 07F .0202", "checked": "2026-11-20", "edition": "NCDOL page, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3004, $kb$sp-sc-trench-1$kb$, md5($kb${"id": "sp-sc-trench-1", "url": "https://osha.llr.sc.gov/pdfs/SC%201926%20standard%20modifications.pdf", "kind": "summary", "text": "South Carolina OSHA has identically adopted the federal standards, according to OSHA's page for the plan, with two unique construction items: excavations and general safety and health requirements. The state's list of changes to 29 CFR 1926 shows the excavation change in the definition of competent person (1926.650(b)): besides being able to identify existing and predictable hazards and having authority to correct them, the competent person \"must have specific training in, and be knowledgeable about, soils analysis, the use of protective systems\" and the requirements of the excavation rule. Federal OSHA says that only in its preamble. Everything else is the federal rule: protection from 5 ft (29 CFR 1926.652), ladder at 4 ft within 25 ft, spoil 2 ft back. The comparison document shows two versions of the definition side by side; reading the first as the state's is our reading of its column order, so that point is not confirmed with the agency. The state's reporting times and any heat rule were not read.", "tier": "core", "state": "SC", "title": "South Carolina trench rule: federal text, with training written into competent person", "topic": "State safety plan: trench and excavation", "source": "SC OSHA, SC 1926 standard modifications (1926.650(b)); OSHA South Carolina State Plan page", "checked": "2026-11-20", "edition": "SC OSHA document, read 2026-11-20", "license": "gov-state", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3232, $kb$fed-811-ticketlife-1$kb$, md5($kb${"id": "fed-811-ticketlife-1", "url": "https://www.ecfr.gov/current/title-49/subtitle-B/chapter-I/subchapter-D/part-196", "kind": "summary", "text": "There is no federal 811 wait time, ticket life or tolerance zone: each state's one-call law sets its own numbers. The federal floor everywhere is 49 CFR 196 for digging near pipelines: use one-call first, wait for the marks, dig with care, report damage, call 911 for a release. Ticket life, from each state's card (use only the job state's line; days are calendar, working or business days as its card says). 14 days: Minnesota, Oklahoma, Texas (working days). 15: Arizona, District of Columbia, New Mexico, South Carolina, Tennessee, Virginia. 20: Alabama, Arkansas, Indiana, Kansas, Louisiana, Mississippi. 21: Kentucky, Michigan, North Dakota, South Dakota, Utah. 25: Iowa, Illinois. 28: California, Hawaii, Nevada, North Carolina. 30: Colorado, Florida, Georgia, Massachusetts, New Hampshire, Oregon, Vermont, Connecticut (app table, not confirmed). 4 weeks: Idaho. 45: New Jersey (business days), Washington. 60: Maine. 12 business days: Delaware, Maryland. Each 14 business days: Wyoming. No set expiry: Alaska, New York, Rhode Island (while marks are kept up), Wisconsin, Ohio (none given, not confirmed). Not confirmed: Missouri, Montana, Nebraska, Pennsylvania, West Virginia.", "tier": "core", "state": "US", "title": "811 ticket life by state: how long is a locate ticket good for in my state?", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Each state's dig-<state> card in this library (state one-call laws and 811 center handbooks, read 2026-11-20); 49 CFR 196.103-196.109", "checked": "2026-11-20", "edition": "State laws as read 2026-11-20; 49 CFR 196 current to Oct 22, 2026", "license": "gov-us", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3233, $kb$fed-811-zone-1$kb$, md5($kb${"id": "fed-811-zone-1", "url": "https://www.ecfr.gov/current/title-49/subtitle-B/chapter-I/subchapter-D/part-196", "kind": "summary", "text": "There is no federal 811 wait time, ticket life or tolerance zone: each state's one-call law sets its own numbers. The federal floor everywhere is 49 CFR 196 for digging near pipelines: use one-call first, wait for the marks, dig with care, report damage, call 911 for a release. Tolerance zone, from each state's card (use only the job state's line; measured from the mark, the edge or plus the line's width as its card says). 18 inches: Alabama (from 2027), Colorado, District of Columbia, Georgia, Illinois, Iowa, Louisiana, Maine, Maryland (not re-read), Massachusetts, Mississippi, Nebraska, New Hampshire, New Mexico, Ohio, Pennsylvania, Rhode Island, South Dakota, Vermont, Wisconsin, Texas (pipelines, plus half the diameter). 24 inches or 2 feet: Alaska, Arizona, California, Delaware, Florida, Idaho, Minnesota, Nevada, New York, North Carolina, North Dakota, Oklahoma, Oregon, South Carolina, Utah, Washington, Wyoming; Kansas, New Jersey, Tennessee, Virginia (in the statute, not re-read). 48 inch caution zone: Michigan. Not confirmed: Arkansas, Connecticut, Hawaii, Indiana, Kentucky, Missouri, Montana, West Virginia.", "tier": "core", "state": "US", "title": "811 tolerance zone (hand-dig zone) by state: 18 inches or 24 inches in my state?", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "Each state's dig-<state> card in this library (state one-call laws and 811 center handbooks, read 2026-11-20); 49 CFR 196.103-196.109", "checked": "2026-11-20", "edition": "State laws as read 2026-11-20; 49 CFR 196 current to Oct 22, 2026", "license": "gov-us", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text)), (3239, $kb$osha-pl-cs-states-2$kb$, md5($kb${"id": "osha-pl-cs-states-2", "url": "https://www.osha.gov/stateplans", "kind": "summary", "note": "Built from the sp-<st>-who-1 / sp-<st>-confined-* cards; IN, IA, KY, SC, VT, WY and MD from official sources read 2026-11-21 (tests/staged/cs_states_nov21/NOTES.md). Hawaii still not confirmed.", "text": "Twenty-one states run their own OSHA plan for private construction crews. A plan must be at least as effective as federal OSHA's confined space in construction rule (29 CFR 1926 Subpart AA) and may be stricter, so name the plan as the source. Use only the line for the job's state. As checked by 2026-11-21. Uses the federal rule, no state change found: Alaska (8 AAC 61.1010(c)), Indiana (from Feb 4, 2016), Iowa (875 IAC 26.1), Kentucky (803 KAR 2:445), Maryland (by reference from Jan 2, 2017), Michigan (Part 35, except as amended), Minnesota, New Mexico, South Carolina (from Aug 28, 2015), Tennessee, Utah, Vermont (Vt. rule 24-050-003), Virginia, Wyoming (WY OSHA chapter 27). Vermont also keeps its own air contaminant table for general industry (CO 35 ppm over 8 hours); whether it reaches construction is not confirmed: ask VOSHA. Not on the plan's unique list, so taken as federal: Arizona, Nevada, North Carolina, Hawaii (not confirmed). Own rule, each has its own card: California (8 CCR 1950 to 1962, amended January 1, 2026, stricter CO limit), Washington (chapter 296-809, all industries), Oregon (437-002-0146; supervisor signs, not initials).", "tier": "core", "state": "US", "title": "State OSHA plans and confined space: which plan states use federal Subpart AA, which have their own rule", "topic": "Confined space rules: which states follow federal OSHA", "source": "osha.gov/stateplans; OSHA State Plan adoption table for the 2015-05-04 Subpart AA rule; each plan's adopting rule as cited in the text; each state card", "checked": "2026-11-21", "edition": "State plan rules as read 2026-11-19 to 2026-11-21 (IN, IA, KY, SC, VT, WY, MD read 2026-11-21)", "license": "gov-us", "confidence": "medium", "unconfirmed": "yes"}$kb$::jsonb::text))) t(o, id, m) on k.ord = t.o and k.chunk->>'id' = t.id and md5(k.chunk::text) = t.m where k.version = 'b3e91f6c47d2') as touched_ok,
       (select count(*) from pb_ai.kb_chunks where version = 'b3e91f6c47d2' and chunk->>'id' in ('sp-wa-confined-air-1', 'osha-pl-powerline-contact-1', 'fed-phmsa-gas-strike-1', 'sp-az-report-1', 'sp-in-report-1', 'sp-nc-report-1', 'sp-tn-report-1', 'sp-vt-report-1', 'sp-nm-report-1', 'osha-pl-report-states-1')) as new_ids_there;
